            ServicesCatalog::default()
        };

        Ok(Self {
            services_path,
            audit_path,
            data: RwLock::new(catalog),
70→        })
    }

    pub async fn get_service(&self, name: &ServiceName) -> Result<Option<ServiceDef>> {
