    }
100→
    pub async fn delete_service(&self, name: &ServiceName) -> Result<()> {
        let mut guard = self.data.write().await;
        if let Some(removed) = guard.services.remove(name.as_str())
            && let Err(error) = self.flush_catalog(&guard).await
